// Cyrus one-account bridge: which hostnames are "the Cyrus app" and where each side lives. PURE (Edge-safe: the
// middleware imports it), HOST SEAM: no Nxeon imports.
//
//   CYRUS_DOMAIN_MODE=1        the switch. Off (default) = nothing in this folder changes any request.
//   CYRUS_HOSTS                comma list of Cyrus hostnames (default "cyrus.my,www.cyrus.my")
//   CYRUS_ORIGIN               the Cyrus app origin (default https://<first CYRUS_HOSTS entry>)
//   APP_URL                    the Nxeon origin (the identity provider + wallet), as everywhere else
export type BridgeConfig = { enabled: boolean; cyrusHosts: string[]; cyrusOrigin: string; nxeonOrigin: string };

const trimSlash = (s: string) => s.replace(/\/+$/, "");

export function bridgeConfig(env: Record<string, string | undefined> = process.env): BridgeConfig {
  const hosts = (env.CYRUS_HOSTS ?? "cyrus.my,www.cyrus.my").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean);
  return {
    enabled: env.CYRUS_DOMAIN_MODE === "1" && hosts.length > 0,
    cyrusHosts: hosts,
    cyrusOrigin: trimSlash(env.CYRUS_ORIGIN || `https://${hosts[0] ?? "cyrus.my"}`),
    nxeonOrigin: trimSlash(env.APP_URL || "https://nxeon.cloud"),
  };
}

/** True only with the mode on AND an exact (port-less, lower-cased) hostname match. */
export function isCyrusHost(host: string | null | undefined, cfg: BridgeConfig = bridgeConfig()): boolean {
  if (!cfg.enabled || !host) return false;
  return cfg.cyrusHosts.includes(host.toLowerCase().split(":")[0]);
}

/** The request header middleware sets on Cyrus-host requests (and strips from every incoming request). */
export const CYRUS_HOST_HEADER = "x-cyrus-host";

/** Session cookie on the Cyrus host. `__Host-` in production: Secure, path=/, no Domain, so it can never be
 *  scoped to a parent domain or set by a sibling host. */
export const cyrusSessionCookie = (env: Record<string, string | undefined> = process.env) =>
  env.NODE_ENV === "production" ? "__Host-cyrus_session" : "cyrus_session";
/** The short-lived sign-in state cookie (state + nonce + next) on whichever host started a handshake. */
export const ssoStateCookie = (side: "cyrus" | "nxeon", env: Record<string, string | undefined> = process.env) =>
  `${env.NODE_ENV === "production" ? "__Host-" : ""}${side}_sso_state`;

/** The fixed callback URLs. Exact-match only: no prefixes, no query, so redirect_uri can never point elsewhere. */
export const callbackUrls = (cfg: BridgeConfig = bridgeConfig()) => ({
  cyrus: `${cfg.cyrusOrigin}/auth/nxeon/callback`,
  nxeon: `${cfg.nxeonOrigin}/sso/cyrus/return`,
});

// ---------------------------------------------------------------------------
// r51 SECRET CYRUS ADMIN HOST (like Nxeon's NXEON_ADMIN_HOSTS / NXEON_STAFF_HOSTS): the Cyrus admin on its own
// non-guessable subdomain of the Cyrus apex. Independent of CYRUS_DOMAIN_MODE. Unset = off (admin stays at
// /admin/cyrus inside the Nxeon admin, exactly as before).
//   CYRUS_ADMIN_HOST        <random label>.cyrus.my (16-63 [a-z0-9]); comma list only while ROTATING (old + new)
//   CYRUS_ADMIN_IPS         optional allowlist (exact IPs, comma list): set = every other client IP gets a 404
//   CYRUS_ADMIN_HOST_ONLY   1 = /admin/cyrus and /api/admin/cyrus 404 on every OTHER host (the move is complete)
// The real hostname lives ONLY in the environment (never in git, docs or tickets); deploy/cyrus/CYRUS-ADMIN-HOST.md.
// ---------------------------------------------------------------------------
export type AdminHostConfig = { hosts: string[]; ips: string[]; only: boolean; invalid: string[] };
const IP_RE = /^(?:\d{1,3}(?:\.\d{1,3}){3}|[0-9a-f:]{2,39})$/i;

export function adminHostConfig(env: Record<string, string | undefined> = process.env): AdminHostConfig {
  const apex = ((env.CYRUS_HOSTS ?? "cyrus.my").split(",")[0] ?? "cyrus.my").trim().toLowerCase().replace(/^www\./, "") || "cyrus.my";
  const want = (env.CYRUS_ADMIN_HOST ?? "").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean);
  const re = new RegExp(`^[a-z0-9]{16,63}\\.${apex.replace(/[.]/g, "\\.")}$`);
  const hosts = want.filter((h) => re.test(h));
  const ips = (env.CYRUS_ADMIN_IPS ?? "").split(",").map((s) => s.trim()).filter((s) => IP_RE.test(s));
  return { hosts, ips, only: env.CYRUS_ADMIN_HOST_ONLY === "1" && hosts.length > 0, invalid: want.filter((h) => !re.test(h)) };
}

export const isCyrusAdminHost = (host: string | null | undefined, cfg: AdminHostConfig = adminHostConfig()) =>
  !!host && cfg.hosts.includes(host.toLowerCase().split(":")[0]);

/** Marker middleware sets on admin-host requests (and strips from every incoming request). */
export const CYRUS_ADMIN_HOST_HEADER = "x-cyrus-admin-host";

/** The client IP as nginx reports it (X-Real-IP = $remote_addr, which a client cannot forge), else the LAST
 *  X-Forwarded-For hop (the one our proxy appended), never the client-supplied leftmost entry. */
export function requestIp(h: { get(name: string): string | null }): string {
  const xff = (h.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
  return h.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
}

/** Allowlist decision. No list = allowed. A list with an unknown client IP = REFUSED (fail closed: the list is explicit). */
export const adminIpAllowed = (ip: string, cfg: AdminHostConfig) => cfg.ips.length === 0 || (!!ip && cfg.ips.includes(ip));
// Cyrus one-account bridge crypto. SERVER ONLY (node:crypto). HOST SEAM: no Nxeon imports.
//
//   identity assertion  b64url(JSON).b64url(Ed25519 sig). The identity provider signs WHO signed in; the relying
//                       party holds only the public key. sub = the stable account id (never an email), bound to the
//                       relying party's nonce, single-use jti, 120 s max lifetime, exact iss/aud.
//   sealed cookie       b64url(JSON).HMAC: the relying party's own state (state, nonce, next, mode), 10 min.
//
// Two signers: "nxeon" (Nxeon -> Cyrus: Sign in with Nxeon) and "cyrus" (Cyrus -> Nxeon: Sign in with Cyrus, and the
// signed logout hop). One app today: both keys are derived from one secret with HKDF (no new secrets to manage).
// On move day each side sets its own private key PEM and the other side's public key (CYRUS_BRIDGE_*_KEY).
import { createHmac, createPrivateKey, createPublicKey, hkdfSync, randomBytes, sign as edSign, timingSafeEqual, verify as edVerify, type KeyObject } from "node:crypto";

export type Signer = "nxeon" | "cyrus";
export type AssertionType = "login" | "logout";
export type Assertion = {
  v: 1; typ: AssertionType; iss: string; aud: string; sub: string; nonce: string; jti: string; iat: number; exp: number;
  /** Hash of the identity provider's own session (the parent), so the child session dies with it. */
  sid?: string | null;
};
export const ASSERTION_MAX_LIFETIME_S = 120;
export const ASSERTION_SKEW_S = 30;
import { SUBJECT_RE } from "./assertion-rules";
export { SUBJECT_RE, NONCE_RE } from "./assertion-rules";

const b64u = (b: Buffer | string) => Buffer.from(b).toString("base64url");
export const randomToken = (bytes = 32) => randomBytes(bytes).toString("base64url");

export function safeEqual(a: string, b: string): boolean {
  const x = Buffer.from(a), y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}

// ------------------------------------------------------------------------------------------------ keys
const PKCS8_ED25519_PREFIX = Buffer.from("302e020100300506032b657004220420", "hex");
type Env = Record<string, string | undefined>;
const ENV_PRIV: Record<Signer, string> = { nxeon: "CYRUS_BRIDGE_NXEON_PRIVATE_KEY", cyrus: "CYRUS_BRIDGE_CYRUS_PRIVATE_KEY" };
const ENV_PUB: Record<Signer, string> = { nxeon: "CYRUS_BRIDGE_NXEON_PUBLIC_KEY", cyrus: "CYRUS_BRIDGE_CYRUS_PUBLIC_KEY" };

function rootSecret(env: Env): string {
  const s = env.CYRUS_BRIDGE_SECRET || env.AUTH_SECRET || "";
  if (s.length < 16) throw new Error("bridge: no signing secret (AUTH_SECRET) configured");
  return s;
}
function derivedPrivate(signer: Signer, env: Env): KeyObject {
  const seed = Buffer.from(hkdfSync("sha256", rootSecret(env), "cyrus-bridge-v1", `ed25519:${signer}`, 32));
  return createPrivateKey({ key: Buffer.concat([PKCS8_ED25519_PREFIX, seed]), format: "der", type: "pkcs8" });
}
export function privateKeyFor(signer: Signer, env: Env = process.env): KeyObject {
  const pem = env[ENV_PRIV[signer]];
  return pem ? createPrivateKey(pem.replace(/\\n/g, "\n")) : derivedPrivate(signer, env);
}
export function publicKeyFor(signer: Signer, env: Env = process.env): KeyObject {
  const pem = env[ENV_PUB[signer]];
  if (pem) return createPublicKey(pem.replace(/\\n/g, "\n"));
  return createPublicKey(privateKeyFor(signer, env));
}
function hmacKey(purpose: string, env: Env): Buffer {
  return Buffer.from(hkdfSync("sha256", rootSecret(env), "cyrus-bridge-v1", `hmac:${purpose}`, 32));
}

// ------------------------------------------------------------------------------------------------ assertions
export function mintAssertion(a: Omit<Assertion, "v" | "iat" | "exp" | "jti"> & { nowMs?: number; ttlS?: number }, key: KeyObject): string {
  const now = Math.floor((a.nowMs ?? Date.now()) / 1000);
  const claims: Assertion = { v: 1, typ: a.typ, iss: a.iss, aud: a.aud, sub: a.sub, nonce: a.nonce, sid: a.sid ?? null, jti: randomToken(16), iat: now, exp: now + Math.min(a.ttlS ?? 90, ASSERTION_MAX_LIFETIME_S) };
  const body = b64u(JSON.stringify(claims));
  return `${body}.${b64u(edSign(null, Buffer.from(body), key))}`;
}

export type AssertionCheck = { ok: true; claims: Assertion } | { ok: false; reason: "malformed" | "bad_signature" | "wrong_party" | "expired" | "nonce" | "replay" };

/** Verifies signature, exact iss/aud/typ, lifetime, the caller's nonce, then claims the jti once (`claimOnce`). */
export function verifyAssertion(raw: string | null | undefined, o: {
  key: KeyObject; iss: string; aud: string; typ: AssertionType; nonce: string | null; nowMs?: number; claimOnce: (jti: string, ttlMs: number) => boolean;
}): AssertionCheck {
  const s = String(raw ?? "");
  const m = /^([A-Za-z0-9_-]{10,4096})\.([A-Za-z0-9_-]{40,200})$/.exec(s);
  if (!m) return { ok: false, reason: "malformed" };
  let good = false;
  try { good = edVerify(null, Buffer.from(m[1]), o.key, Buffer.from(m[2], "base64url")); } catch { good = false; }
  if (!good) return { ok: false, reason: "bad_signature" };
  let c: Assertion;
  try { c = JSON.parse(Buffer.from(m[1], "base64url").toString("utf8")); } catch { return { ok: false, reason: "malformed" }; }
  if (c?.v !== 1 || typeof c.sub !== "string" || !SUBJECT_RE.test(c.sub) || typeof c.jti !== "string" || typeof c.iat !== "number" || typeof c.exp !== "number") return { ok: false, reason: "malformed" };
  if (c.typ !== o.typ || c.iss !== o.iss || c.aud !== o.aud) return { ok: false, reason: "wrong_party" };
  const now = Math.floor((o.nowMs ?? Date.now()) / 1000);
  if (c.exp - c.iat > ASSERTION_MAX_LIFETIME_S || c.iat > now + ASSERTION_SKEW_S || c.exp < now - ASSERTION_SKEW_S) return { ok: false, reason: "expired" };
  if (o.nonce !== null && (typeof c.nonce !== "string" || !safeEqual(c.nonce, o.nonce))) return { ok: false, reason: "nonce" };
  if (!o.claimOnce(`cyrus-bridge:jti:${c.jti}`, (ASSERTION_MAX_LIFETIME_S + ASSERTION_SKEW_S * 2) * 1000)) return { ok: false, reason: "replay" };
  return { ok: true, claims: c };
}

// ------------------------------------------------------------------------------------------------ sealed cookies
export function seal(purpose: string, data: Record<string, unknown>, ttlS: number, env: Env = process.env, nowMs = Date.now()): string {
  const body = b64u(JSON.stringify({ ...data, e: Math.floor(nowMs / 1000) + ttlS }));
  return `${body}.${createHmac("sha256", hmacKey(purpose, env)).update(body).digest("base64url")}`;
}
export function unseal<T extends Record<string, unknown>>(purpose: string, raw: string | null | undefined, env: Env = process.env, nowMs = Date.now()): T | null {
  const m = /^([A-Za-z0-9_-]{4,4096})\.([A-Za-z0-9_-]{43})$/.exec(String(raw ?? ""));
  if (!m) return null;
  const want = createHmac("sha256", hmacKey(purpose, env)).update(m[1]).digest("base64url");
  if (!safeEqual(want, m[2])) return null;
  try {
    const d = JSON.parse(Buffer.from(m[1], "base64url").toString("utf8"));
    if (typeof d?.e !== "number" || d.e < Math.floor(nowMs / 1000)) return null;
    return d as T;
  } catch { return null; }
}
// Cyrus one-account bridge: the handshake's pure rules (parameter checks, URLs, error codes). HOST SEAM: no Nxeon imports.
//
//   Sign in with Nxeon (cyrus.my):  /auth/nxeon/start -> Nxeon /sso/cyrus/authorize (login / register + consent,
//     verified email) -> /auth/nxeon/callback?code=<Ed25519 assertion>&state -> Cyrus session cookie.
//   Sign in with Cyrus (nxeon.cloud): /sso/cyrus/start -> cyrus.my /auth/handoff (needs a Cyrus session, which itself
//     came from Nxeon) -> Nxeon /sso/cyrus/return -> Nxeon session. Same account both ways: sub = the account id.
import { callbackUrls, type BridgeConfig } from "./config";
import { NONCE_RE } from "./assertion-rules";
import { decodeAttribution, encodeAttribution } from "../analytics/consent";

export type ClientId = "cyrus" | "nxeon";
export type Prompt = "login" | "create";
/** attr (r44): the consented cyrus.my attribution (lib/cyrus/analytics/consent encodeAttribution), re-validated here. */
export type AuthorizeParams = { clientId: ClientId; redirectUri: string; state: string; nonce: string; prompt: Prompt; attr?: string };

/** Re-validate an arriving attribution value; null when absent or anything is off (never stored as-is). */
export function cleanAttr(raw: string | null | undefined): string | undefined {
  const a = decodeAttribution(raw);
  return a ? encodeAttribution(a) ?? undefined : undefined;
}

/** Exact client + exact redirect_uri + well-formed state/nonce, or null (the caller answers 400, never redirects). */
export function parseAuthorize(q: URLSearchParams, expect: ClientId, cfg: BridgeConfig): AuthorizeParams | null {
  const clientId = q.get("client_id"), redirectUri = q.get("redirect_uri"), state = q.get("state") ?? "", nonce = q.get("nonce") ?? "";
  if (clientId !== expect) return null;
  if (redirectUri !== callbackUrls(cfg)[expect]) return null;
  if (!NONCE_RE.test(state) || !NONCE_RE.test(nonce)) return null;
  const p = q.get("prompt");
  const attr = cleanAttr(q.get("attr"));
  return { clientId: expect, redirectUri, state, nonce, prompt: p === "create" ? "create" : "login", ...(attr ? { attr } : {}) };
}

export function authorizeQuery(p: AuthorizeParams): string {
  const q = new URLSearchParams({ client_id: p.clientId, redirect_uri: p.redirectUri, state: p.state, nonce: p.nonce });
  if (p.prompt === "create") q.set("prompt", "create");
  if (p.attr) q.set("attr", p.attr);
  return q.toString();
}

/** Back to the (vetted) redirect_uri with a code or an error code, plus the caller's state. */
export function callbackUrl(p: Pick<AuthorizeParams, "redirectUri" | "state">, r: { code: string } | { error: BridgeError }): string {
  const u = new URL(p.redirectUri);
  if ("code" in r) u.searchParams.set("code", r.code);
  else u.searchParams.set("error", r.error);
  u.searchParams.set("state", p.state);
  return u.toString();
}

/** The only error codes that ever travel in a URL; each page maps them to fixed copy (never echoes input). */
export const BRIDGE_ERRORS = {
  access_denied: "Sign-in was cancelled.",
  impersonating: "Stop impersonating on Nxeon first.",
  state: "That sign-in link expired or didn't match. Please try again.",
  assertion: "We couldn't verify the sign-in. Please try again.",
  account: "This account can't sign in here.",
  unverified: "Verify your email on Nxeon first, then try again.",
  staff: "Staff accounts sign in to Nxeon with their password.",
  ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
} as const;
export type BridgeError = keyof typeof BRIDGE_ERRORS;
/** "Continue with Google" on cyrus.my (CYRUS_GOOGLE_LOGIN): fixed copy per code, never any Google-supplied text. */
export const GOOGLE_ERRORS = {
  google_unavailable: "Google sign-in isn't available right now. Use Sign in with Nxeon instead.",
  google_cancelled: "Google sign-in was cancelled.",
  google_failed: "We couldn't finish signing in with Google. Please try again.",
  google_state: "That Google sign-in expired or didn't match. Please try again.",
  google_unverified: "Google says that email address isn't verified, so we can't use it.",
} as const;
export type GoogleError = keyof typeof GOOGLE_ERRORS;
export const bridgeErrorText = (code: string | null | undefined): string | null => {
  if (!code) return null;
  if (Object.prototype.hasOwnProperty.call(BRIDGE_ERRORS, code)) return BRIDGE_ERRORS[code as BridgeError];
  if (Object.prototype.hasOwnProperty.call(GOOGLE_ERRORS, code)) return GOOGLE_ERRORS[code as GoogleError];
  return null;
};

// Cyrus one-account bridge, platform side: the route handlers' shared plumbing (mode gate, rate limits, the sealed
// state/consent cookies, absolute redirects). The protocol itself is lib/cyrus/bridge (seam-clean); this file is
// allowed to use Nxeon (lib/auth, lib/rate-limit) because it IS the identity provider and the session issuer.
import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { bridgeConfig, CYRUS_HOST_HEADER, ssoStateCookie, type BridgeConfig } from "@/lib/cyrus/bridge/config";
import { randomToken, seal, unseal } from "@/lib/cyrus/bridge/assertion";
import { checkRateLimit, claimOnce, clientIp } from "@/lib/rate-limit";
import { emailVerificationError, isEmailVerified, isGrandfathered } from "@/lib/email-verification";

export { claimOnce };
const prod = () => process.env.NODE_ENV === "production";

/** The handler's gate: mode on AND the request is on the expected side. Otherwise the route does not exist. */
export function bridgeGate(req: Request, side: "cyrus" | "nxeon"): BridgeConfig | null {
  const cfg = bridgeConfig();
  if (!cfg.enabled) return null;
  const onCyrus = req.headers.get(CYRUS_HOST_HEADER) === "1";
  return (side === "cyrus") === onCyrus ? cfg : null;
}
export const notFound = () => new NextResponse("Not found.", { status: 404 });

/** Per-IP limit for every bridge leg (handshakes are cheap to start; abuse should not be). */
export function limited(req: Request, bucket: string, max = 30): boolean {
  return !checkRateLimit(`cyrus-bridge:${bucket}:${clientIp(req)}`, { max, windowMs: 60_000 }).ok;
}

/** 302/303 to an absolute URL on one of the two configured origins, never cached, no Referer leak of codes. */
export function go(url: string, status: 302 | 303 = 302): NextResponse {
  const res = NextResponse.redirect(url, status);
  res.headers.set("Cache-Control", "no-store");
  res.headers.set("Referrer-Policy", "no-referrer");
  return res;
}

export type SsoState = { s: string; n: string; next: string; m?: "create" };
const STATE_TTL_S = 600;

/** Start a handshake: fresh state + nonce sealed into a host-only, httpOnly, Lax cookie on THIS side. */
export async function beginHandshake(side: "cyrus" | "nxeon", next: string, mode?: "create"): Promise<SsoState> {
  const st: SsoState = { s: randomToken(24), n: randomToken(24), next, ...(mode ? { m: mode } : {}) };
  (await cookies()).set(ssoStateCookie(side), seal(`state:${side}`, st, STATE_TTL_S), {
    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: STATE_TTL_S,
  });
  return st;
}
/** Read AND delete the handshake cookie (one callback per start). */
export async function takeHandshake(side: "cyrus" | "nxeon"): Promise<SsoState | null> {
  const jar = await cookies();
  const raw = jar.get(ssoStateCookie(side))?.value;
  // r49 (re-audit A-L1): a __Host- cookie can only be cleared by a Secure Set-Cookie (jar.delete sends none)
  jar.set(ssoStateCookie(side), "", { httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: 0 });
  return unseal<SsoState & { e: number }>(`state:${side}`, raw);
}

// ---- consent (Nxeon side): remembered per browser + account; a pre-account grant covers one sign-up handshake.
const CONSENT_COOKIE = () => `${prod() ? "__Host-" : ""}nxeon_cyrus_consent`;
type Consent = { u?: string; pre?: string };
export async function hasConsent(userId: string, nonce: string): Promise<boolean> {
  const c = unseal<Consent & { e: number }>("consent", (await cookies()).get(CONSENT_COOKIE())?.value);
  return !!c && (c.u === userId || c.pre === nonce);
}
export async function grantConsent(g: { userId?: string; nonce?: string }): Promise<void> {
  const ttl = g.userId ? 365 * 86_400 : 1_800;
  (await cookies()).set(CONSENT_COOKIE(), seal("consent", g.userId ? { u: g.userId } : { pre: g.nonce }, ttl), {
    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: ttl,
  });
}
/** CSRF token for the consent form, bound to the handshake nonce and the account (or "" before sign-up). */
export const consentCsrf = (nonce: string, userId: string) => seal("consent-csrf", { n: nonce, u: userId }, 900);
export function checkConsentCsrf(raw: string | null, nonce: string, userId: string): boolean {
  const c = unseal<{ n: string; u: string; e: number }>("consent-csrf", raw);
  return !!c && c.n === nonce && c.u === userId;
}

/** Same-origin check for state-changing POSTs (in addition to SameSite=Lax cookies). */
export function sameOrigin(req: Request, origin: string): boolean {
  const o = req.headers.get("origin");
  return o === origin;
}

/**
 * Verified-email rule for the bridge. STRICT by default: the account must have confirmed its email (or predate
 * verification, like everywhere in Nxeon). Nxeon's own purchase gate fails open while mail deliverability is
 * unproven (email_verification_enforced); CYRUS_BRIDGE_REQUIRE_VERIFIED=0 makes the bridge follow that rule instead.
 */
export async function bridgeEmailBlocked(user: Parameters<typeof emailVerificationError>[0]): Promise<boolean> {
  if (process.env.CYRUS_BRIDGE_REQUIRE_VERIFIED === "0") return (await emailVerificationError(user)) !== null;
  return !isEmailVerified(user) && !isGrandfathered(user);
}

/**
 * After a FORM POST, continue with a plain navigation instead of a redirect: the site CSP has form-action 'self', and
 * browsers apply form-action to every redirect that follows a form submission, so a 303 that ends cross-origin
 * (consent -> authorize -> cyrus.my, cyrus.my logout -> Nxeon) would be blocked. `url` is always one we built.
 */
export function continueTo(url: string): Response {
  const esc = url.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  return new Response(
    `<!doctype html><meta charset="utf-8"><meta name="referrer" content="no-referrer"><meta http-equiv="refresh" content="0;url=${esc}"><title>Continuing</title><p><a href="${esc}">Continue</a></p>`,
    { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "referrer-policy": "no-referrer" } },
  );
}
import { db } from "@/lib/db";
import { createCyrusSession } from "@/lib/auth";
import { recordRequestActivity } from "@/lib/activity-request";
import { modBuilderAccess } from "@/lib/modbuilder/access";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { recordConversion, saveAttributionSnapshot } from "@/lib/cyrus/analytics/conversions";
import { CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE } from "@/lib/cyrus/analytics/consent";
import { safeEqual, verifyAssertion, publicKeyFor } from "@/lib/cyrus/bridge/assertion";
import { BRIDGE_ERRORS } from "@/lib/cyrus/bridge/flow";
import { bridgeEmailBlocked, bridgeGate, claimOnce, go, limited, notFound, takeHandshake } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * cyrus.my callback: our state cookie (constant-time match, consumed), then Nxeon's assertion (Ed25519, exact
 * iss/aud/typ, our nonce, 120 s, single-use jti). The account is matched by its stable id ONLY (never email), must
 * exist, not be suspended and have a verified email. Then the Cyrus-host session cookie (lib/auth createCyrusSession),
