export type HostRateLimit = { ok: boolean; retryAfterSec: number; remaining: number };

/** The signed-in person as Cyrus sees them. The platform's own user record is a superset of this. */
export type HostUser = { id: string; email: string | null; role: string; name?: string | null };
/** A permission area of the host's admin ("billing", "support"...). Opaque to Cyrus; each host defines its own. */
export type HostArea = string;
/** Private-preview feature keys Cyrus may ask about. */
export type HostPreviewFeature = "modbuilder";

/** A game server's filesystem as installers see it (absolute guest paths). Structurally identical to the platform's GuestFs. */
export interface HostGuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  copy(from: string, to: string): Promise<void>;
}
/** What the host knows about a game server (the guest itself is asked separately). */
export type HostServerFacts = { id: string; family: string; variant: string | null; pinnedVersion: string | null; config: Record<string, unknown> | null };
/** What the host's catalogue knows about a mod; Cyrus mints these for its own sources ("cyrus", managed plugins, mod packs). */
export type HostModFacts = {
  id: string; gameFamily: string; slug: string; name: string; source: string; sourceId: string | null; url: string | null; category: string;
  appliesToVariant: string | null; loaders: string[]; gameVersions: string[]; serverSide: string | null; targetVersionId?: string | null;
};
export type HostResolvedPackage = {
  key: string; name: string; version: string; versionId?: string | null;
  file: { url: string; filename: string; size: number | null; hashes: { sha1?: string | null; sha256?: string | null; sha512?: string | null } };
  /** "plugin-jar" | "datapack" for Minecraft. */
  placement: string;
  requires: string[]; incompatible: { key: string; name: string }[];
  /** The bytes, already fetched and verified by Cyrus: the host never downloads for Cyrus. */
  prefetched?: Buffer;
  root: boolean;
};
export type HostResolution = { packages: HostResolvedPackage[]; notes: string[]; alsoBackupDirs?: string[] };
export type HostInstallResult =
  | { ok: true; version?: string; versionId?: string | null; fileName?: string | null; restartRequired: boolean; changed: string[]; notes: string[] }
  | { ok: false; error: string };

/** A game server row as Cyrus reads it. The platform's own row is a superset. */
export type HostServerRow = {
  id: string; status: string; label?: string | null; hostname: string; gameVariant: string | null; gameConfig: unknown;
  osTemplate?: { family: string } | null;
};
/** One mod installed on one server (the platform's install record). */
export type HostInstallRow = {
  serverId: string; modId: string; versionId: string | null; status: string; error: string | null; updatedAt: Date; autoUpdate: string | null;
  mod: { source: string; sourceId: string | null; name: string };
};

export interface CyrusHost {
  /** Cyrus' own database (see CyrusDb). Use through lib/cyrus/db.ts (cyrusDb), not directly. */
  db: CyrusDb;
  /** Who is signed in. Sessions, cookies and impersonation stay entirely the host's business. */
  auth: {
    /** The acting user (impersonation applied), or null when signed out. */
    currentUser(): Promise<HostUser | null>;
    /** The really signed-in user, ignoring impersonation, or null. */
