    canAccess(role: string, area: HostArea): boolean;
    isPreviewUser(user: { email?: string | null } | null | undefined, feature: HostPreviewFeature): Promise<boolean>;
  };
  /** Key/value settings and feature flags (Nxeon: the Setting table). Values are strings; missing keys use the fallback. */
  settings: {
    get(key: string, fallback?: string): Promise<string>;
    getBool(key: string, fallback?: boolean): Promise<boolean>;
    getInt(key: string, fallback?: number): Promise<number>;
    getAll(): Promise<Record<string, string>>;
    set(key: string, value: string): Promise<void>;
    /** Values exactly as stored (no defaults, no cache): for admin editors that must tell "unset" from "default". */
    readStored(keys: string[]): Promise<Record<string, string>>;
    readStoredPrefix(prefix: string): Promise<Record<string, string>>;
    writeStored(key: string, value: string): Promise<void>;
    clearStored(key: string): Promise<void>;
  };
