    modLifecycleSweep(): Promise<unknown>;
    /** Creator warnings about game versions the mod no longer fits. */
    modCompatWatchSweep(): Promise<unknown>;
    /** Advance in-flight AI mod builds from the build service. */
    syncModBuilds(): Promise<unknown>;
    /** Perf safety: watch customer servers for a few minutes after a Cyrus install; disable/roll back a mod that keeps
