    perfWatchSweep?(): Promise<unknown>;
  };
  /** Accounts, by id. Billing identity is the host's; Cyrus only reads the basics and stores the payment customer id it creates. */
  users: {
    get(id: string): Promise<{ id: string; email: string } | null>;
    emails(ids: string[]): Promise<{ id: string; email: string }[]>;
    /** By email (case-insensitive) when `query` contains "@", otherwise by id. */
    find(query: string): Promise<{ id: string; email: string } | null>;
