    /** The newest "health" mod-update run on a server (log-read verdicts), or null. */
    lastHealthRun(serverId: string): Promise<{ startedAt: Date; plan: unknown } | null>;
    /** File access to ONE of this user's servers (null when it is not theirs, gone, or being deleted); `base` is the game folder on it. */
    openFiles(userId: string, serverId: string): Promise<{ fs: HostGuestFs; base: string; close?: () => void } | null>;
    /** The game version pinned in a server's config, when it names a real one. */
    pinnedVersion(config: unknown): string | null;
