  /** What the host has recorded as installed (its ServerMod/GameMod records). */
  records: {
    /** Installs on one server whose catalogue source is `source`. */
    onServer(serverId: string, source: string): Promise<HostInstallRow[]>;
    /** Which of `serverIds` have at least one install from `source` (each id once). */
