    allOnServer?(serverId: string): Promise<{ name: string; version: string | null; source: string; fileName: string | null; status: string; via: "mods-tab" | "cyrus" | "managed" | "other" }[]>;
  };
  /** Putting Cyrus' files on a server through the host's install engine (which keeps the host's own record of what it placed). */
  installs: {
    /** The engine's state file on the server; a pack install snapshots it so a failed install also undoes the bookkeeping. */
    readonly statePath: string;
    /** Place the prefetched package(s) of `resolution` for `mod`. Never downloads: a download attempt fails with `noDownloadMessage`. */
    install(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; resolution: HostResolution; mode: "install" | "update"; noDownloadMessage: string }): Promise<HostInstallResult>;
    /** Remove what the engine recorded for `mod` (and dependencies nothing else needs). */
    uninstall(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; noDownloadMessage: string }): Promise<HostInstallResult>;
  };
  /** Cyrus' build engine (lib/modbuilder: build rows, the build-service sync, the access rule). It is Cyrus' own code that
