  builds: {
    /** Pull the build service's view of one build into its row (settles token holds when it finished). Never throws for an unreachable service. */
    sync(row: ModBuild): Promise<ModBuild>;
    /** Start a build or a change for `user` (plan, token and rate gates included). `body` is the build API's JSON. */
    create(user: User, body: Record<string, unknown>): Promise<CreateBuildResult>;
    /** The signed-in account allowed to use the Mod Builder (preview/public rule), or null. */
    accessUser(): Promise<User | null>;
    /** The same access rule for one account by id, without a session (API subjects), or null. */
    accountFor(userId: string): Promise<User | null>;
