  mail?: {
    send(m: { to: string; from: string; replyTo?: string; subject: string; html: string; text: string; userId: string }): Promise<boolean>;
  };
  /** r44: ad-conversion transports (Meta CAPI event, Google Ads offline conversion) for lib/cyrus/analytics/conversions.
