  subject: string;
  data: { idemKey: string; kind: "topup" | "storage"; method: "wallet" | "card"; tokens: number; cents: number; expiresAt: string | null; note: string | null; refundedCents?: number;
    /** r44 card top-ups: the provider's ids, kept in the ledger exactly as the direct path stored them */
    sourceRef?: string; paymentIntent?: string | null; livemode?: boolean };
};
export type HostBilling = {
  /** "host" = the platform is the payment provider (default); "own-stripe" = Cyrus' own Stripe account. */
  provider: "host" | "own-stripe";
  stripe: HostStripe | null;
  wallet: HostWallet | null;
  /** Deliver a purchase event to Cyrus over the signed webhook path (CYRUS_PURCHASE_EVENTS). Absent = credit directly. */
  emitPurchase?: (e: PurchaseEnvelope) => Promise<void>;
  /** A user's plan/token entitlement changed on the payment provider's side: tell Cyrus (Nxeon: the signed
   *  entitlement.changed event, CYRUS_PLATFORM_EVENTS). Absent = nothing to tell (one app, or no events). */
  entitlementChanged?: (userId: string) => Promise<unknown>;
};

