// Personal Cyrus API keys (r39). A key is "cyk_" + 8-char public prefix + "_" + 40 random base62 characters.
// Only sha256(key) is stored; the plain key is returned once, at creation. Scopes are a subset of the API v1 scopes
// that a customer may hold (never admin). Store behind an interface so tests and a standalone Cyrus can swap it.
import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
import { SCOPES, type Scope } from "../api/v1/scopes";

/** What a personal key may carry: everything in v1 except staff scopes. */
export const PERSONAL_SCOPES = SCOPES.filter((s) => s !== "admin:read") as Exclude<Scope, "admin:read">[];
export type PersonalScope = (typeof PERSONAL_SCOPES)[number];
export const SCOPE_LABEL: Record<PersonalScope, string> = {
  "projects:read": "Read projects", "projects:write": "Change projects", "builds:read": "Read builds", "builds:write": "Start builds (spends tokens)",
  "installs:read": "Read installs", "installs:write": "Install to servers", "catalog:read": "Read the catalog", "config:write": "Change mod config",
  "library:write": "Contribute to the library", "mods:read": "Read mod pages", "account:read": "Read account and tokens", "webhooks:manage": "Manage webhooks",
};
export const MAX_ACTIVE_KEYS = 10;
export const KEY_NAME_MAX = 48;
const KEY_RE = /^cyk_([A-Za-z0-9]{8})_([A-Za-z0-9]{40})$/;

export type ApiKeyRow = { id: string; userId: string; name: string; prefix: string; sha256: string; scopes: string[]; createdAt: Date; lastUsedAt: Date | null; expiresAt: Date | null; revokedAt: Date | null };
export type ApiKeyView = { id: string; name: string; prefix: string; scopes: PersonalScope[]; createdAt: string; lastUsedAt: string | null; expiresAt: string | null; revokedAt: string | null; active: boolean };

export interface ApiKeyStore {
  listForUser(userId: string): Promise<ApiKeyRow[]>;
  insert(row: Omit<ApiKeyRow, "id" | "createdAt" | "lastUsedAt" | "revokedAt">): Promise<ApiKeyRow>;
  /** Revoke only if the key belongs to userId; returns false otherwise (never reveals another user's key). */
  revoke(userId: string, id: string, at: Date): Promise<boolean>;
  bySha(sha256: string): Promise<ApiKeyRow | null>;
  touch(id: string, at: Date): Promise<void>;
}

const B62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
function base62(n: number): string {
  let out = "";
  while (out.length < n) { for (const b of randomBytes(n * 2)) { if (b < 248 && out.length < n) out += B62[b % 62]; } }
  return out;
}
export const sha256Hex = (s: string) => createHash("sha256").update(s, "utf8").digest("hex");

export function newKeyMaterial(): { key: string; prefix: string; sha256: string } {
  const prefix = base62(8), secret = base62(40), key = `cyk_${prefix}_${secret}`;
  return { key, prefix, sha256: sha256Hex(key) };
}

export function parseScopes(raw: unknown): { ok: true; scopes: PersonalScope[] } | { ok: false; error: string } {
  const arr = Array.isArray(raw) ? raw : typeof raw === "string" ? [raw] : [];
  const out = [...new Set(arr.map(String))];
  if (!out.length) return { ok: false, error: "Pick at least one permission." };
  const bad = out.find((s) => !(PERSONAL_SCOPES as readonly string[]).includes(s));
  if (bad) return { ok: false, error: `Unknown permission: ${bad.slice(0, 40)}` };
  return { ok: true, scopes: PERSONAL_SCOPES.filter((s) => out.includes(s)) };
}

export function parseKeyName(raw: unknown): { ok: true; name: string } | { ok: false; error: string } {
  const n = String(raw ?? "").replace(/[\u0000-\u001f\u007f]/g, "").trim();
  if (!n) return { ok: false, error: "Give the key a name." };
  if (n.length > KEY_NAME_MAX) return { ok: false, error: `Keep the name under ${KEY_NAME_MAX} characters.` };
  return { ok: true, name: n };
}

const EXPIRY_DAYS = [0, 30, 90, 365] as const;
export function parseExpiry(raw: unknown, now: Date): { ok: true; at: Date | null } | { ok: false; error: string } {
  const d = Number(raw ?? 90);
  if (!(EXPIRY_DAYS as readonly number[]).includes(d)) return { ok: false, error: "Pick an expiry." };
  return { ok: true, at: d === 0 ? null : new Date(now.getTime() + d * 86_400_000) };
}

export const isActive = (r: Pick<ApiKeyRow, "revokedAt" | "expiresAt">, now: Date) => !r.revokedAt && (!r.expiresAt || r.expiresAt > now);

export function toView(r: ApiKeyRow, now: Date): ApiKeyView {
  return {
